// Generates the Flutter token layer from design/system/tokens.json (Lock L35, audit Appendix C).
// Output: apps/mobile/lib/src/theme/doktool_tokens.dart. Replaces the handoff file, whose spacing
// members (`static const double 1`) were not valid Dart.
import { camelCase, themedTokens, toDartArgb } from './drift.mjs';

const HEADER = `// GENERATED by packages/design-tokens (npm run generate:dart -w @doktool/design-tokens)
// from design/system/tokens.json — do not edit by hand.`;

const px = (value) => {
  const number = Number.parseFloat(String(value));
  if (!Number.isFinite(number)) throw new Error(`not a length: ${value}`);
  return number.toFixed(1);
};
const ms = (value) => Number.parseInt(String(value), 10);
const doc = (usage) => (usage ? ` // ${String(usage).replace(/\s+/g, ' ').slice(0, 110)}` : '');

/** Dart member name for a token, without its category prefix: "radius-sm" → "sm", "space-4" → "s4". */
function member(name, prefix) {
  const rest = name.slice(prefix.length);
  const identifier = camelCase(rest);
  return /^[0-9]/.test(identifier) ? `s${identifier}` : identifier;
}

function scalarClass(className, comment, tokens, prefix, render = px) {
  const lines = tokens.map(
    (t) => `  static const double ${member(t.name, prefix)} = ${render(t.value)};${doc(t.usage)}`,
  );
  return `/// ${comment}\nabstract final class ${className} {\n${lines.join('\n')}\n}`;
}

/** "0 8px 24px rgba(11,31,51,0.10), 0 2px 6px rgba(...)" → Dart BoxShadow list. */
function boxShadows(css) {
  if (css.trim() === 'none') return '<BoxShadow>[]';
  const layers = css.split(/,(?![^(]*\))/).map((layer) => layer.trim());
  const items = layers.map((layer) => {
    const match =
      /^(-?[\d.]+)(?:px)?\s+(-?[\d.]+)(?:px)?\s+([\d.]+)(?:px)?(?:\s+(-?[\d.]+)(?:px)?)?\s+(rgba?\([^)]+\)|#[0-9a-fA-F]{6})$/.exec(
        layer,
      );
    if (!match) throw new Error(`unsupported shadow "${layer}"`);
    const [, x, y, blur, spread, color] = match;
    return `BoxShadow(offset: Offset(${px(x)}, ${px(y)}), blurRadius: ${px(blur)}, spreadRadius: ${px(spread ?? 0)}, color: Color(0x${toDartArgb(color.replace(/\s+/g, ''))}))`;
  });
  return `<BoxShadow>[${items.join(', ')}]`;
}

export function generateDart(source) {
  const themed = themedTokens(source);
  const colourNames = source.color.tokens.map((t) => t.name);
  const fields = colourNames.map(camelCase);
  const colour = (theme, name) => themed.find((t) => t.theme === theme && t.name === name).value;

  const colourValues = (theme) =>
    colourNames
      .map((name) => `    ${camelCase(name)}: Color(0x${toDartArgb(colour(theme, name))}),`)
      .join('\n');

  const colours = `@immutable
class DtColors extends ThemeExtension<DtColors> {
  const DtColors({${fields.map((f) => `required this.${f}`).join(', ')}});

${source.color.tokens.map((t) => `  /// ${String(t.usage ?? t.name).replace(/\s+/g, ' ')}\n  final Color ${camelCase(t.name)};`).join('\n')}

  static const light = DtColors(
${colourValues('light')}
  );

  static const dark = DtColors(
${colourValues('dark')}
  );

  @override
  DtColors copyWith({${fields.map((f) => `Color? ${f}`).join(', ')}}) =>
      DtColors(${fields.map((f) => `${f}: ${f} ?? this.${f}`).join(', ')});

  @override
  DtColors lerp(ThemeExtension<DtColors>? other, double t) {
    if (other is! DtColors) return this;
    return DtColors(${fields.map((f) => `${f}: Color.lerp(${f}, other.${f}, t)!`).join(', ')});
  }
}`;

  const shadowNames = source.shadow.tokens.map((t) => t.name);
  const shadowFields = shadowNames.map((n) => camelCase(n.slice('shadow-'.length)));
  const shadowValues = (theme) =>
    shadowNames
      .map(
        (name, i) =>
          `    ${shadowFields[i]}: ${boxShadows(themed.find((t) => t.theme === theme && t.name === name).value)},`,
      )
      .join('\n');
  const elevation = `/// Shadows per theme (tokens "shadow-*").
@immutable
class DtElevation extends ThemeExtension<DtElevation> {
  const DtElevation({${shadowFields.map((f) => `required this.${f}`).join(', ')}});

${shadowFields.map((f) => `  final List<BoxShadow> ${f};`).join('\n')}

  static const light = DtElevation(
${shadowValues('light')}
  );

  static const dark = DtElevation(
${shadowValues('dark')}
  );

  @override
  DtElevation copyWith({${shadowFields.map((f) => `List<BoxShadow>? ${f}`).join(', ')}}) =>
      DtElevation(${shadowFields.map((f) => `${f}: ${f} ?? this.${f}`).join(', ')});

  @override
  DtElevation lerp(ThemeExtension<DtElevation>? other, double t) {
    if (other is! DtElevation) return this;
    return DtElevation(${shadowFields.map((f) => `${f}: BoxShadow.lerpList(${f}, other.${f}, t)!`).join(', ')});
  }
}`;

  const durations = source.duration.tokens
    .map(
      (t) =>
        `  static const Duration ${member(t.name, 'duration-')} = Duration(milliseconds: ${ms(t.value)});${doc(t.usage)}`,
    )
    .join('\n');
  const curves = source.easing.tokens
    .map((t) => {
      const match = /cubic-bezier\(([^)]+)\)/.exec(t.value);
      if (!match) throw new Error(`unsupported easing ${t.value}`);
      const args = match[1].split(',').map((n) => Number.parseFloat(n).toString());
      return `  static const Curve ${camelCase(t.name)} = Cubic(${args.join(', ')});${doc(t.usage)}`;
    })
    .join('\n');
  const motion = `/// Motion: only these durations and curves (Lock L9).\nabstract final class DtMotion {\n${durations}\n${curves}\n}`;

  const styles = source.type.groups.flatMap((group) =>
    group.styles.map((style) => ({ ...style, family: group.family })),
  );
  const tabular = new Set(['numeric', 'result', 'mono']);
  const weight = (w) => `FontWeight.w${w}`;
  const textStyle = (s) => {
    const size = Number.parseFloat(s.fontSize);
    const height = (Number.parseFloat(s.lineHeight) / size).toFixed(4);
    const parts = [
      `fontFamily: ${s.family === 'mono' ? 'monoFamily' : 'sansFamily'}`,
      `fontSize: ${size.toFixed(1)}`,
      `height: ${height}`,
      `fontWeight: ${weight(s.fontWeight)}`,
    ];
    if (s.letterSpacing)
      parts.push(`letterSpacing: ${(Number.parseFloat(s.letterSpacing) * size).toFixed(2)}`);
    if (tabular.has(s.name)) parts.push('fontFeatures: [FontFeature.tabularFigures()]');
    return `  /// ${String(s.usage).replace(/\s+/g, ' ')}\n  static const TextStyle ${camelCase(s.name)} = TextStyle(${parts.join(', ')});`;
  };
  const type = `/// Type scale. Inter and JetBrains Mono are bundled app fonts (Lock L19).
abstract final class DtType {
  static const sansFamily = 'Inter';
  static const monoFamily = 'JetBrainsMono';
${styles.map(textStyle).join('\n')}
}`;

  const theme = `/// Material theme built from the tokens. Widgets read DtColors / DtElevation with
/// \`Theme.of(context).extension<DtColors>()!\` — never a raw colour (Lock L35).
ThemeData dtTheme(Brightness brightness) {
  final c = brightness == Brightness.light ? DtColors.light : DtColors.dark;
  final e = brightness == Brightness.light ? DtElevation.light : DtElevation.dark;
  return ThemeData(
    brightness: brightness,
    useMaterial3: true,
    fontFamily: DtType.sansFamily,
    scaffoldBackgroundColor: c.bg,
    splashFactory: NoSplash.splashFactory,
    colorScheme: ColorScheme(
      brightness: brightness,
      primary: c.brand,
      onPrimary: c.onBrand,
      secondary: c.teal,
      onSecondary: c.onTeal,
      error: c.critical,
      onError: c.onBrand,
      surface: c.surface,
      onSurface: c.ink,
      outline: c.borderStrong,
      outlineVariant: c.border,
    ),
    dividerColor: c.border,
    textTheme: TextTheme(
      headlineSmall: DtType.display.copyWith(color: c.ink),
      titleLarge: DtType.title.copyWith(color: c.ink),
      titleMedium: DtType.heading.copyWith(color: c.ink),
      bodyLarge: DtType.body.copyWith(color: c.ink),
      bodyMedium: DtType.body.copyWith(color: c.ink),
      labelLarge: DtType.label.copyWith(color: c.ink),
      bodySmall: DtType.caption.copyWith(color: c.inkMuted),
    ),
    extensions: <ThemeExtension<dynamic>>[c, e],
  );
}`;

  return (
    [
      HEADER,
      `import 'package:flutter/material.dart';`,
      colours,
      elevation,
      scalarClass(
        'DtSpace',
        'Spacing scale in logical pixels (tokens "space-N" → sN).',
        source.spacing.tokens,
        'space-',
      ),
      scalarClass('DtRadius', 'Corner radii.', source.radius.tokens, 'radius-'),
      scalarClass(
        'DtBlur',
        'Backdrop blur sigma for Clinical Glass, with the opaque surface fallback.',
        source.blur.tokens,
        'blur-',
      ),
      scalarClass('DtOpacity', 'Opacities.', source.opacity.tokens, 'opacity-', (v) =>
        Number.parseFloat(v).toString(),
      ),
      scalarClass('DtBorder', 'Border widths.', source.border.tokens, 'border-'),
      scalarClass('DtSize', 'Fixed sizes; heights are minimums.', source.size.tokens, 'size-'),
      scalarClass(
        'DtBreakpoint',
        'Layout breakpoints (the phone layout is kept on tablets at a constrained width).',
        source.breakpoint.tokens,
        'bp-',
      ),
      motion,
      type,
      theme,
    ].join('\n\n') + '\n'
  );
}
